            failures += expect(output, "gf_windows_paint_endpoint_table.configure offset", (long)((byte*)&value.configure - start), 16);
            failures += expect(output, "gf_windows_paint_endpoint_table.touch offset", (long)((byte*)&value.touch - start), 24);
            failures += expect(output, "gf_windows_paint_endpoint_table.drain offset", (long)((byte*)&value.drain - start), 32);
            failures += expect(output, "gf_windows_paint_endpoint_table.snapshot offset", (long)((byte*)&value.snapshot - start), 40);
            failures += expect(output, "gf_windows_paint_endpoint_table.submit_bgra offset", (long)((byte*)&value.submit_bgra - start), 48);
            failures += expect(output, "gf_windows_paint_endpoint_table.release offset", (long)((byte*)&value.release - start), 56);
            failures += expect(output, "gf_windows_paint_endpoint_table.get_dc offset", (long)((byte*)&value.get_dc - start), 64);
            failures += expect(output, "gf_windows_paint_endpoint_table.release_dc offset", (long)((byte*)&value.release_dc - start), 72);
            failures += expect(output, "gf_windows_paint_endpoint_table.publish_dc offset", (long)((byte*)&value.publish_dc - start), 80);
            failures += expect(output, "gf_windows_paint_endpoint_table.begin_write offset", (long)((byte*)&value.begin_write - start), 88);
            failures += expect(output, "gf_windows_paint_endpoint_table.end_write offset", (long)((byte*)&value.end_write - start), 96);
        }
        return failures;
    }

    private static int expect(TextWriter output, string what, long actual, long expected)
    {
        if (actual == expected)
        {
            return 0;
        }
        output.WriteLine($"layout: {what} is {actual}, the manifest says {expected}");
        return 1;
    }
}
